        "p": "গৌরকিশোর দাস বাবাজি যখন তিনবার দীক্ষা দিতে অস্বীকার করেন, তিনি হাল ছাড়েননি। তিনি ঘোষণা করেন যে গুরুর কৃপা ছাড়া তিনি বাঁচতে পারবেন না, এবং শেষে তাঁর চোখের জলই সেই কৃপা এনে দেয়। তিনি বিশ্বস্তভাবে গুরুসেবা করেছেন, এবং বাবাজির অপ্রকটের সময় যাঁরা লাভের জন্য তাঁর দেহ চেয়েছিলেন, একা তাঁদের বিরুদ্ধে দাঁড়িয়ে নিজেই গুরুদেবকে সমাধিস্থ করেন।"
