    "biography": [
      {
        "p": "শ্রীল রঘুনাথ ভট্ট গোস্বামী (1503-1579), কৃষ্ণলীলায় রাগমঞ্জরী, বারাণসীর তপন মিশ্রের পুত্র ছিলেন। মহাপ্রভু যখন তাঁর পিতার গৃহে ছিলেন, বালক রঘুনাথ তাঁর বাসন মাজতেন ও পা টিপে দিতেন। পরে তিনি একেকবার আট মাস করে পুরীতে ভগবানের সঙ্গে থাকতেন, এবং এত দক্ষতার সঙ্গে রান্না করতেন যে মহাপ্রভু তাঁর তৈরি সবকিছু আস্বাদন করতেন। ভগবান তাঁকে বিয়ে না করতে, ভক্ত পিতামাতার সেবা করতে, এবং শেষে রূপ ও সনাতনের তত্ত্বাবধানে বৃন্দাবনে যেতে বলেন। সেখানে তিনি তিন সুরে শ্রীমদ্ভাগবতম পাঠের জন্য বিখ্যাত হন, প্রায়ই প্রেমে কণ্ঠরুদ্ধ হয়ে যেত। তিনি তাঁর শিষ্য রাজা মানসিংহকে গোবিন্দজি মন্দির নির্মাণে অনুপ্রাণিত করেন এবং শ্রীবিগ্রহের জন্য অলংকার তৈরি করেন। তিনি কখনও জাগতিক বিষয়ে কথা বলতেন না, বা কোনো বৈষ্ণবের নিন্দা শুনতেন না। ষড় গোস্বামীর মধ্যে একমাত্র তিনিই কোনো গ্রন্থ রেখে যাননি। তাঁর সমাধি রাধাকুণ্ডে এবং গোবিন্দজি মন্দিরের কাছে।"
      },
      {
        "p": "ব্রজে যাওয়ার আগে, ভগবানের নির্দেশ অনুযায়ী, তিনি চার বছর বারাণসীতে বৃদ্ধ ভক্ত পিতামাতার সেবা করেন এবং এক উপলব্ধিসম্পন্ন বৈষ্ণবের কাছে ভাগবত অধ্যয়ন করেন। ভগবান তাঁকে নিজের কণ্ঠমালা, শ্রীজগন্নাথের পরা চোদ্দ হাত লম্বা তুলসীমালা এবং পান দেন, যা তিনি পূজা করতেন ও স্মরণে গলায় ধারণ করতেন। অসম্মানের আশঙ্কায় জীব গোস্বামী তাঁর দেহ দাহ করান; তাঁর ভস্ম রাধাকুণ্ডের তিন গোস্বামী সমাধিতে এবং গোবিন্দজির কাছে চৌষট্টি সমাধি এলাকায় রয়েছে।"
      }
    ],
