    "summary": "বিশ্বনাথ চক্রবর্তীর শিষ্য, যিনি 1706 সালে জয়পুরের গলতায় ‘গোবিন্দভাষ্য’ রচনা করে বেদান্ত সম্প্রদায়গুলির মধ্যে গৌড়ীয় সম্প্রদায়ের স্থান সুপ্রতিষ্ঠিত করেন।",
    "biography": [
      {
        "p": "শ্রীল বলদেব বিদ্যাভূষণ, চৈতন্যলীলায় গোপীনাথ আচার্য এবং কৃষ্ণলীলায় রত্নাবলী বলে বর্ণিত, ওড়িশার রেমুণার কাছে জন্মগ্রহণ করেন। মেধাবী পণ্ডিত বলদেব প্রথমে মাধ্ব পরম্পরায় সন্ন্যাসী হন, যতদিন না রসিকানন্দের শিষ্য রাধা-দামোদর দেব গোস্বামী তাঁকে মহাপ্রভুর শিক্ষার সঙ্গে পরিচয় করান। পরে তিনি বৃন্দাবনে বিশ্বনাথ চক্রবর্তী ঠাকুরের কাছে অধ্যয়ন করেন। 1706 সালে জয়পুরের কাছে গলতার রামানন্দীরা যখন গৌড়ীয়দের গোবিন্দজির সেবার অধিকার নিয়ে প্রশ্ন তোলেন, কারণ তাঁদের কোনো বেদান্তসূত্র ভাষ্য ছিল না, বলদেব শ্রীগোবিন্দের কাছে প্রার্থনা করেন। স্বপ্নে ভগবান একটি ভাষ্য বলে দেওয়ার প্রতিশ্রুতি দেন, এবং বলদেব ‘গোবিন্দভাষ্য’ রচনা করেন, যা বিরোধীদের নীরব করে দেয় এবং তাঁকে ‘বিদ্যাভূষণ’, অর্থাৎ বিদ্যাই যাঁর অলংকার, উপাধি এনে দেয়। তিনি আরও কুড়িটিরও বেশি গ্রন্থ লেখেন, যার মধ্যে আছে ‘প্রমেয়রত্নাবলী’ ও ‘গীতাভাষ্য’। তিনি শ্রীজয়-বিজয় গোবিন্দের সেবা করতেন এবং 1768 সালে বৃন্দাবনে অপ্রকট হন।"
      },
      {
        "p": "মত পরিবর্তনের আগে তিনি বিজয়ী পণ্ডিত হিসেবে ভ্রমণ করে বহু তীর্থস্থানের পণ্ডিতদের পরাস্ত করেন। তাঁর বিজয়ের পর রামানন্দীরা তাঁর কাছে দীক্ষা চাইলেও শ্রী সম্প্রদায়ের প্রতি শ্রদ্ধাবশত তিনি তা প্রত্যাখ্যান করেন। এরপর জয়পুরের মহারাজা আদেশ দেন যে গোবিন্দজির আরতি সবার আগে হবে। পরে তিনি জীব গোস্বামীর ‘ষট্‌সন্দর্ভ’-এর একটি ভাষ্য শুরু করেন। গোবিন্দ দাস নামেও পরিচিত এই আচার্যের শিষ্যদের মধ্যে ছিলেন উদ্ধব দাস, যাঁর পরম্পরা জগন্নাথ দাস বাবাজি পর্যন্ত পৌঁছেছে। গলতায় তাঁর ছোট মন্দিরে আজও প্রায় একশোটি শালগ্রাম শিলা রয়েছে।"
      }
    ],
